using System.ClientModel;
using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ── Configuration ──────────────────────────────────────────────────────────────
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
var model  = Environment.GetEnvironmentVariable("OPENAI_MODEL")  ?? "gpt-4o-mini";

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Set the OPENAI_API_KEY environment variable to run the agent.");
    return 1;
}

// ── Tools ──────────────────────────────────────────────────────────────────────
var notebook = new Notebook();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(WebSearchTool.Search),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// ── Chat client with automatic tool invocation ─────────────────────────────────
IChatClient client = new OpenAIClient(new ApiKeyCredential(apiKey))
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()          // auto-invokes tools when the model requests them
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ── Prompt ─────────────────────────────────────────────────────────────────────
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("No topic provided.");
    return 1;
}

var systemPrompt = $$"""
    You are a research agent. Your goal is to thoroughly research the topic the user
    gives you and produce a well-organised summary.

    Workflow:
    1. Break the topic into 2-3 key questions.
    2. For each question, call the web_search tool with a relevant query.
    3. Read the results and save important facts with the add_note tool.
    4. When you have gathered enough information, call get_notes to review everything.
    5. Finally, write a concise, well-structured summary with sections and cite your sources.

    Always search at least twice before writing the final summary.
    """;

List<ChatMessage> messages =
[
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Research this topic: {topic}"),
];

Console.WriteLine($"\n🔍  Researching \"{topic}\" …\n");

// ── Agent loop ─────────────────────────────────────────────────────────────────
var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("─── Research Summary ───────────────────────────────────────\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n────────────────────────────────────────────────────────────");
Console.WriteLine($"  Notes collected : {notebook.Count}");
Console.WriteLine($"  Total tokens    : {response.Usage?.TotalTokenCount}");

return 0;

// ═══════════════════════════════════════════════════════════════════════════════
//  Tool implementations
// ═══════════════════════════════════════════════════════════════════════════════

/// <summary>Provides a web search tool that fetches real results via DuckDuckGo Lite.</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public static async Task<string> Search(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐  Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo's HTML lite endpoint (no API key needed)
            var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
            var html = await Http.GetStringAsync(url);

            var results = ParseDdgResults(html);

            if (results.Count == 0)
                return "No results found.";

            return string.Join("\n\n", results.Take(5));
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<string> ParseDdgResults(string html)
    {
        // Simple parser for DuckDuckGo Lite result snippets
        var results = new List<string>();
        var span = html.AsSpan();

        const string titleMarker  = "class=\"result__a\"";
        const string snippetMarker = "class=\"result__snippet\"";

        int pos = 0;
        while (pos < span.Length && results.Count < 5)
        {
            // Find next title
            int titleIdx = html.IndexOf(titleMarker, pos, StringComparison.Ordinal);
            if (titleIdx < 0) break;

            var title = ExtractTagContent(html, titleIdx);

            // Find next snippet
            int snippetIdx = html.IndexOf(snippetMarker, titleIdx, StringComparison.Ordinal);
            var snippet = snippetIdx >= 0 ? ExtractTagContent(html, snippetIdx) : "";

            if (!string.IsNullOrWhiteSpace(title))
                results.Add($"**{title.Trim()}**\n{snippet.Trim()}");

            pos = Math.Max(titleIdx + 1, snippetIdx + 1);
        }

        return results;
    }

    private static string ExtractTagContent(string html, int attrPos)
    {
        int gt = html.IndexOf('>', attrPos);
        if (gt < 0) return "";
        int lt = html.IndexOf('<', gt);
        if (lt < 0) return "";
        return System.Net.WebUtility.HtmlDecode(html[( gt + 1)..lt]).Trim();
    }
}

/// <summary>An in-memory notebook that the agent uses to collect research notes.</summary>
sealed class Notebook
{
    private readonly List<string> _notes = [];

    public int Count => _notes.Count;

    [Description("Save an important fact or finding to the notebook for later reference.")]
    public string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝  Note #{_notes.Count} saved");
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes yet.";

        return string.Join("\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }
}

